"use strict";

/*
=========================================================
GARGO HAVEN DEPOT — shared branding + print helpers
Loaded before the other modules (after jsPDF).
  GH_BRAND               logo/header image (JPEG data URI) + aspect ratio
  ghPdfLetterhead()      stamps the header onto a jsPDF page
  ghPrintHeaderHtml()    same header for HTML print windows / modals
  ghPrintPdf(doc)        prints a jsPDF document without downloading it
To change the logo: replace headerJpeg below (keep ~1200px wide, JPEG).
=========================================================
*/

window.GH_BRAND = {
  name: 'Gargo Haven Depot Limited',
  /* The same wording as printed in the letterhead image. Used as the top rows of Excel / CSV exports, which cannot carry the image. */
  lines: ['GARGO HAVEN DEPOT LIMITED', 'Refinery Road Changamwe, Mombasa', 'P.O. BOX 3291 GPO MSA'],
  aspect: 1200 / 195,
  headerJpeg: 'data:image/jpeg;base64,',
};

/* Draws the letterhead at (x, y) with width w (mm). Returns the y just below it. */
window.ghPdfLetterhead = function (doc, x, y, w) {
  const h = w / window.GH_BRAND.aspect;
  try {
    doc.addImage(window.GH_BRAND.headerJpeg, 'JPEG', x, y, w, h, undefined, 'FAST');
  } catch (e) {
    console.warn('Letterhead could not be drawn, falling back to text', e);
    doc.setFont(undefined, 'bold'); doc.setFontSize(14); doc.setTextColor(20);
    doc.text('GARGO HAVEN DEPOT LIMITED', x, y + 8);
    doc.setFont(undefined, 'normal'); doc.setFontSize(8); doc.setTextColor(110);
    doc.text('Refinery Road Changamwe, Mombasa · P.O. Box 3291 GPO MSA', x, y + 13);
  }
  return y + h;
};

/* Header block for HTML print windows (print-safe, keeps colours). */
window.ghPrintHeaderHtml = function () {
  return '<div style="border-bottom:2px solid #c9a227;padding-bottom:8px;margin-bottom:12px;' +
    '-webkit-print-color-adjust:exact;print-color-adjust:exact">' +
    '<img src="' + window.GH_BRAND.headerJpeg + '" alt="' + window.GH_BRAND.name + '" ' +
    'style="height:80px;width:auto;max-width:100%;display:block"></div>';
};

/* Same header for on-screen modals (dark theme) — sits on a light card so the logo colours read correctly. */
window.ghModalHeaderHtml = function (maxWidth) {
  return '<div style="background:#fafaf8;border-radius:8px;padding:6px 10px;display:inline-block;max-width:100%">' +
    '<img src="' + window.GH_BRAND.headerJpeg + '" alt="' + window.GH_BRAND.name + '" ' +
    'style="width:' + (maxWidth || 360) + 'px;max-width:100%;height:auto;display:block"></div>';
};

/* Prints a jsPDF document directly (no file saved). Falls back to opening it in a new tab. */
window.ghPrintPdf = function (doc) {
  let url;
  try {
    url = URL.createObjectURL(doc.output('blob'));
  } catch (e) {
    console.error('Could not prepare PDF for printing', e);
    if (window.toast) toast('Could not prepare document for printing', 'error');
    return;
  }
  const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) ||
    (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  const openTab = () => {
    const w = window.open(url, '_blank');
    if (!w && window.toast) toast('Pop-up blocked — allow pop-ups to print', 'error');
  };
  // iOS Safari can't print from a hidden frame; the PDF viewer tab has its own print/share menu.
  if (isIOS) { openTab(); return; }

  const f = document.createElement('iframe');
  f.style.cssText = 'position:fixed;left:-10000px;top:0;width:800px;height:1100px;border:0;visibility:hidden';
  f.onload = () => {
    setTimeout(() => {
      try { f.contentWindow.focus(); f.contentWindow.print(); }
      catch (e) { console.warn('Frame print failed, opening in tab', e); openTab(); }
    }, 350);
    setTimeout(() => { URL.revokeObjectURL(url); f.remove(); }, 120000);
  };
  f.src = url;
  document.body.appendChild(f);
};